#include <string.h> // Required for strlen
#include <stdio.h>  // Required for snprintf

/**
Generates a welcome message for the user with the specified username. This message will be redendered in a HTML page after the user logs in. The message will be in the format "Welcome, <username>!".

@param username The username of the user.

@return The welcome message for further rendering.
*/
char* get_welcome_message(const char* username) {
    // Robustness check: Ensure username is not NULL before proceeding.
    // Attempting to call strlen or snprintf with a NULL username would lead to a crash.
    if (username == NULL) {
        return NULL; // Indicate an invalid input by returning NULL.
    }

    // Calculate the length needed for the new string:
    // "Welcome, " (9 chars) + username length + "!" (1 char) + null terminator (1 char)
    size_t username_len = strlen(username);

    // Defensive check against potential integer overflow for total_len.
    // The constant part is 9 (for "Welcome, ") + 1 (for "!") + 1 (for null terminator) = 11.
    // If username_len is extremely large, adding 11 could exceed SIZE_MAX.
    // While highly unlikely for practical username lengths, this check ensures robustness.
    if (username_len > (SIZE_MAX - 11)) {
        return NULL; // Indicate an error due to excessive length that would cause overflow
    }

    size_t total_len = 9 + username_len + 1 + 1; // 9 for "Welcome, ", 1 for "!", 1 for null terminator

    // Allocate memory for the welcome message
    char* welcome_message = (char*)malloc(total_len);

    // Check if memory allocation was successful
    if (welcome_message == NULL) {
        return NULL; // Return NULL if memory allocation failed
    }

    // Construct the welcome message using snprintf for safety and conciseness.
    // snprintf writes at most total_len-1 characters, ensuring null termination.
    // It returns the number of characters that would have been written if the buffer
    // had been sufficiently large, not counting the null terminator.
    int chars_written = snprintf(welcome_message, total_len, "Welcome, %s!", username);

    // Check for snprintf errors or unexpected truncation.
    // A negative value indicates an encoding error.
    // If chars_written is >= total_len, it means the output was truncated,
    // which should not happen with the calculated total_len, but is a good
    // defensive check.
    if (chars_written < 0 || (size_t)chars_written >= total_len) {
        free(welcome_message); // Free allocated memory on error or truncation
        return NULL;           // Return NULL to indicate failure
    }

    return welcome_message;
}
